insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-eq-146', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'For the gas reaction $\mathrm{A} \rightleftharpoons \mathrm{B} + \mathrm{C}$ starting with 1 mol of A in volume $V$, $K_c$ equals', '["$\\alpha^2 / ((1-\\alpha)V)$","$\\alpha / V$","$(1-\\alpha)/\\alpha^2$","$\\alpha^2 V$"]'::jsonb, 0, '[B] = [C] = $\alpha/V$, [A] = $(1-\alpha)/V$, so $K_c = (\alpha/V)^2 / ((1-\alpha)/V) = \alpha^2/((1-\alpha)V)$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'degree-dissociation') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
