insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-eq-151', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'For $\mathrm{PCl_5} \rightleftharpoons \mathrm{PCl_3} + \mathrm{Cl_2}$, $K_p$ in terms of $\alpha$ and the total pressure $P$ is', '["$\\alpha^2 P / (1 - \\alpha^2)$","$\\alpha P$","$(1 - \\alpha)/P$","$4\\alpha^2 P / (1 - \\alpha^2)$"]'::jsonb, 0, 'Mole fractions give $p_{PCl3} = p_{Cl2} = \alpha P/(1+\alpha)$ and $p_{PCl5} = (1-\alpha)P/(1+\alpha)$, whence $K_p = \alpha^2 P/(1-\alpha^2)$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'degree-dissociation') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
